-- =====================================================================
-- v12：练习单元、活动与题目知识点映射
-- 内容：2 个知识点 + 26 道题挂到 8 个已发布单元 + 题目 nodeCode 回填
-- 依赖：v11（节点注册与清理）
-- 执行：mysql -uroot -p --default-character-set=utf8mb4 oslab_db < 本文件
-- 说明：全部幂等；由当前库导出，重建库后练习页仍显示 26 题。
-- =====================================================================
SET NAMES utf8mb4;

-- 练习单元、活动与题目知识点映射（由当前库导出，幂等）


UPDATE `learning_question_node` SET `nodeCode`='os.interrupt' WHERE `nodeName` IN ('中断','时钟中断');
UPDATE `learning_question_node` SET `nodeCode`='os.syscall' WHERE `nodeName` IN ('系统调用');
UPDATE `learning_question_node` SET `nodeCode`='os.files' WHERE `nodeName` IN ('文件');
UPDATE `learning_question_node` SET `nodeCode`='os.memory' WHERE `nodeName` IN ('地址映射','内存管理');
UPDATE `learning_question_node` SET `nodeCode`='os.memory.virtual' WHERE `nodeName` IN ('虚拟内存管理');
UPDATE `learning_question_node` SET `nodeCode`='os.memory.page-table' WHERE `nodeName` IN ('页表','两级页表机制');
UPDATE `learning_question_node` SET `nodeCode`='os.memory.tlb' WHERE `nodeName` IN ('TLB','TLB 重填','TLB 缺失');
UPDATE `learning_question_node` SET `nodeCode`='os.memory.page-fault' WHERE `nodeName` IN ('缺页中断');
UPDATE `learning_question_node` SET `nodeCode`='os.memory.page-replacement' WHERE `nodeName` IN ('页面置换','FIFO','LRU 页面置换算法');
UPDATE `learning_question_node` SET `nodeCode`='os.process' WHERE `nodeName` IN ('进程','进程控制块');
UPDATE `learning_question_node` SET `nodeCode`='os.process.scheduling' WHERE `nodeName` IN ('时间片轮转算法','进程调度','CPU 调度');
UPDATE `learning_question_node` SET `nodeCode`='os.process.switch' WHERE `nodeName` IN ('进程切换');
UPDATE `learning_question_node` SET `nodeCode`='os.process.state' WHERE `nodeName` IN ('进程状态');
UPDATE `learning_question_node` SET `role`='PRIMARY' WHERE `role` IS NULL;



SELECT (SELECT COUNT(*) FROM `learning_unit` WHERE `publishedJson` IS NOT NULL) AS published_units,
       (SELECT COUNT(*) FROM `learning_unit_activity` WHERE `isDelete`=0) AS activities,
       (SELECT COUNT(*) FROM `learning_question_node` WHERE `nodeCode` IS NULL) AS unmapped_nodes;
